window.products.push({"id":1110155,"name":"Kubberd Cold Brew Coffee Maker - Iced And Pitcher 2L Large Airtight Shatterproof Carafe","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/71uTNg544kL._AC_SL1500_.jpg","description":"3 Steps to Amazing Cold Brew. Step 1: Grind. Choose a medium-to-coarse grind. For ready-to-drink cold brew, start with a ratio of 1 cup of ground coffee to 8 cups of water (then adjust from there). Step 2: Brew. Allow the ground coffee to steep in the water for 12-24 hours at room temperature or in the refrigerator. Longer brew time will result in stronger coffee. Step 3: Remove the filtered grounds and Enjoy. Remove the ultra fine mesh filter and discard the used coffee grounds. Pour cold brew over ice, add milk or cream as desired. Enjoy!","images":["https://m.media-amazon.com/images/I/71uTNg544kL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Kubberd","source_asin":"B09JYFTQW4","category_path":"Home & Kitchen"},"sku":"BM-1110155","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B09JYFTQW4","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B09JYFTQW4","price_pending":true,"merchant_ready":false});
